select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":5339,"materia":"ml","nivel":0,"enunciado":"O exame dos vestígios deixados por um crime é chamado de:","opcoes":["Exame de corpo de delito","Inquérito policial completo","Boletim de ocorrência","Auto de prisão em flagrante"],"explicacao":"Pode ser direto (sobre os vestígios) ou indireto (por outras provas)."},{"id":5340,"materia":"ml","nivel":0,"enunciado":"O exame interno e externo do cadáver, para descobrir a causa da morte, é a:","opcoes":["Necropsia (autópsia)","Exumação do cadáver sepultado","Biópsia","Tomografia"],"explicacao":"No Brasil, é feita nos IMLs em mortes violentas ou suspeitas."},{"id":5341,"materia":"ml","nivel":0,"enunciado":"O endurecimento dos músculos depois da morte é chamado de:","opcoes":["Rigidez cadavérica (rigor mortis)","Livor mortis","Algor mortis (esfriamento do corpo)","Mumificação"],"explicacao":"Depois de algumas horas, a rigidez começa a desaparecer."},{"id":5342,"materia":"ml","nivel":0,"enunciado":"Soco, pedrada e paulada são exemplos de ação de instrumento:","opcoes":["Contundente","Cortante","Perfurante","Perfurocortante"],"explicacao":"O instrumento contundente age por pressão, choque ou atrito."},{"id":5343,"materia":"ml","nivel":0,"enunciado":"O reagente que revela manchas de sangue invisíveis a olho nu, brilhando no escuro, é o:","opcoes":["Luminol","Iodo","Álcool","Formol"],"explicacao":"É muito usado em locais de crime que foram limpos."},{"id":5344,"materia":"ml","nivel":0,"enunciado":"A lesão corporal que não causa nenhuma das consequências de lesão grave ou gravíssima é classificada como:","opcoes":["Leve","Gravíssima","Grave","Seguida de morte"],"explicacao":"Exemplos: escoriações e pequenas equimoses."},{"id":5345,"materia":"ml","nivel":0,"enunciado":"São sinais imediatos de morte:","opcoes":["Perda da consciência e parada da respiração e da circulação","Formação de livores, mancha verde abdominal e início da putrefação","Rigidez completa e putrefação","Mumificação e saponificação"],"explicacao":"Livores, rigidez e putrefação surgem depois."},{"id":5346,"materia":"ml","nivel":0,"enunciado":"Ferimentos nas mãos e nos antebraços de quem tentou se proteger de facadas são chamados de:","opcoes":["Lesões de defesa","Lesões de hesitação","Lesões post mortem","Lesões autoprovocadas"],"explicacao":"Ajudam a diferenciar homicídio de suicídio."},{"id":5347,"materia":"ml","nivel":0,"enunciado":"O IML de Salvador, ligado ao Departamento de Polícia Técnica da Bahia, leva o nome de:","opcoes":["Nina Rodrigues","Oswaldo Cruz","Carlos Chagas","Afrânio Peixoto"],"explicacao":"Raimundo Nina Rodrigues foi pioneiro da Medicina Legal no Brasil."},{"id":5348,"materia":"ml","nivel":0,"enunciado":"O estudo dos insetos que colonizam o cadáver, para estimar o tempo de morte, é a:","opcoes":["Entomologia forense","Odontologia legal","Toxicologia forense","Antropologia física"],"explicacao":"Moscas costumam chegar ao corpo em poucas horas."},{"id":5349,"materia":"ml","nivel":1,"enunciado":"Pelo Código Penal, a lesão que deixa a vítima incapaz para as ocupações habituais por mais de 30 dias é:","opcoes":["Grave","Leve","Gravíssima","Culposa"],"explicacao":"A prova costuma vir do exame complementar."},{"id":5350,"materia":"ml","nivel":1,"enunciado":"Pelo Código Penal, a lesão corporal que causa perigo de vida é:","opcoes":["Grave","Leve","Gravíssima","Privilegiada"],"explicacao":"O perigo deve ser concreto e demonstrado pela perícia."},{"id":5351,"materia":"ml","nivel":1,"enunciado":"Pelo Código Penal, a lesão que causa perda ou inutilização de membro, sentido ou função é:","opcoes":["Gravíssima","Leve","Grave, por debilidade","Simples"],"explicacao":"Se houver só debilidade permanente, a lesão é grave."},{"id":5352,"materia":"ml","nivel":1,"enunciado":"Pelo CPP, quando a infração deixa vestígios, o exame de corpo de delito:","opcoes":["É indispensável e não pode ser suprido pela confissão","Pode ser dispensado sempre que o acusado confessar o crime","Só é feito se o juiz pedir","É sempre facultativo"],"explicacao":"Previsão do art. 158 do CPP."},{"id":5353,"materia":"ml","nivel":1,"enunciado":"A rede de veias escurecidas que aparece na pele durante a putrefação é chamada de:","opcoes":["Circulação póstuma de Brouardel","Manchas de Tardieu e de Paltauf","Sinal de Sommer","Orla de enxugo"],"explicacao":"Surge na fase gasosa, pela ação dos gases da decomposição."},{"id":5354,"materia":"ml","nivel":1,"enunciado":"Lesões com infiltração de sangue e reação inflamatória indicam que foram produzidas:","opcoes":["Em vida (reação vital)","Depois da morte","Por ação da fauna cadavérica","Por putrefação"],"explicacao":"Lesões post mortem não têm reação vital."},{"id":5355,"materia":"ml","nivel":1,"enunciado":"Corpo com livores de cor rosa-avermelhada (vermelho-cereja) sugere intoxicação por:","opcoes":["Monóxido de carbono","Cianeto (ácido cianídrico)","Arsênio","Álcool"],"explicacao":"O CO se liga à hemoglobina formando carboxi-hemoglobina."},{"id":5356,"materia":"ml","nivel":1,"enunciado":"Cheiro de amêndoas amargas no cadáver sugere envenenamento por:","opcoes":["Cianeto","Monóxido de carbono","Chumbo","Organofosforado"],"explicacao":"Nem todas as pessoas conseguem sentir esse odor."},{"id":5357,"materia":"ml","nivel":2,"enunciado":"A constrição do pescoço por laço movido por força diferente do peso do corpo, com sulco horizontal e contínuo, é o:","opcoes":["Estrangulamento","Enforcamento incompleto","Esganadura","Afogamento"],"explicacao":"No enforcamento, o sulco costuma ser oblíquo e interrompido."},{"id":5358,"materia":"ml","nivel":2,"enunciado":"Pelo Código Penal (art. 129, § 2º), a lesão que causa enfermidade incurável é:","opcoes":["Gravíssima","Leve","Grave","Culposa, com pena reduzida"],"explicacao":"Também é gravíssima a que causa deformidade permanente ou aborto."},{"id":5359,"materia":"ml","nivel":2,"enunciado":"Pelo CPP, se o primeiro exame não bastar para classificar a lesão como grave por incapacidade de mais de 30 dias, faz-se:","opcoes":["Exame complementar logo após o prazo de 30 dias","Novo inquérito policial","Apenas prova testemunhal, sem nenhum outro exame pericial","Exumação do corpo"],"explicacao":"A falta do exame pode ser suprida por prova testemunhal (art. 168, § 3º)."},{"id":5360,"materia":"ml","nivel":2,"enunciado":"Pelo CPP, o exame de corpo de delito é feito por:","opcoes":["Um perito oficial com diploma de curso superior","Três peritos policiais nomeados pelo delegado, sempre","O delegado de polícia","Qualquer testemunha do fato"],"explicacao":"Na falta de perito oficial, duas pessoas idôneas com curso superior."},{"id":5361,"materia":"ml","nivel":2,"enunciado":"Pelo CPP, se os vestígios desapareceram e não é possível o exame de corpo de delito:","opcoes":["A prova testemunhal pode suprir a falta","O processo é sempre anulado","A confissão basta sozinha","O réu deve ser absolvido de imediato, por falta de materialidade"],"explicacao":"Previsão do art. 167 do CPP."},{"id":5362,"materia":"ml","nivel":2,"enunciado":"A ordem das fases da putrefação é:","opcoes":["Coloração, gasosa, coliquativa e esqueletização","Gasosa, coloração, esqueletização e coliquativa","Esqueletização, coliquativa, gasosa e coloração","Coliquativa, coloração, gasosa e esqueletização"],"explicacao":"A mancha verde abdominal marca a fase de coloração."},{"id":5363,"materia":"ml","nivel":2,"enunciado":"Hímen complacente é aquele que:","opcoes":["Permite a conjunção carnal sem se romper","Sempre se rompe na primeira relação sexual, sem exceção","Não existe na mulher adulta","Indica gravidez"],"explicacao":"Por isso, a integridade do hímen não exclui conjunção carnal."},{"id":5364,"materia":"ml","nivel":2,"enunciado":"Pelo CP, o semi-imputável (perturbação da saúde mental) tem a pena:","opcoes":["Reduzida de 1/3 a 2/3","Aumentada de 1/3","Excluída por completo","Substituída sempre por multa"],"explicacao":"Também pode receber medida de segurança, se necessário."},{"id":5365,"materia":"ml","nivel":2,"enunciado":"Os fenômenos cadavéricos transformativos destrutivos são:","opcoes":["Autólise, putrefação e maceração","Mumificação, saponificação e corificação","Rigidez e livores","Esfriamento e desidratação"],"explicacao":"Mumificação e saponificação são fenômenos conservadores."},{"id":5366,"materia":"ml","nivel":3,"enunciado":"Pelo CPP (art. 158-B), a primeira etapa da cadeia de custódia é o:","opcoes":["Reconhecimento","Descarte","Processamento do vestígio","Armazenamento"],"explicacao":"Depois vêm isolamento, fixação, coleta, acondicionamento e transporte."},{"id":5367,"materia":"ml","nivel":3,"enunciado":"A rigidez instantânea, que mantém o corpo na posição exata do momento da morte, é o:","opcoes":["Espasmo cadavérico (rigidez cataléptica)","Rigor mortis comum, de evolução lenta e progressiva","Livor mortis","Algor mortis"],"explicacao":"É raro e ligado a mortes súbitas com forte tensão muscular."},{"id":5368,"materia":"ml","nivel":3,"enunciado":"A mancha escura na esclera do cadáver de olhos abertos, por dessecamento, é o sinal de:","opcoes":["Sommer-Larcher","Werkgaertner-Puppe","Benassi","Amussat"],"explicacao":"É um fenômeno abiótico consecutivo."},{"id":5369,"materia":"ml","nivel":3,"enunciado":"A progressão da rigidez cadavérica da cabeça para os pés é descrita pela lei de:","opcoes":["Nysten","Galeno","Vucetich","Bertillon"],"explicacao":"A rigidez também desaparece na mesma ordem."},{"id":5370,"materia":"ml","nivel":3,"enunciado":"No crânio, o orifício de entrada do projétil tem bisel (funil) voltado para a tábua:","opcoes":["Interna (sinal do funil de Bonnet)","Externa, como na saída","Nenhuma, sem bisel","Externa e interna ao mesmo tempo, sem diferença entre elas"],"explicacao":"Na saída, o bisel fica na tábua externa."},{"id":5371,"materia":"ml","nivel":3,"enunciado":"Pequenas hemorragias puntiformes sob a pleura, comuns nas asfixias, são as manchas de:","opcoes":["Tardieu","Paltauf","Brouardel","Lichtenberg"],"explicacao":"No afogamento, as manchas de Paltauf são maiores e mais claras."},{"id":5372,"materia":"ml","nivel":3,"enunciado":"Desenhos em forma de ramos de árvore na pele de vítima de raio são o sinal de:","opcoes":["Lichtenberg","Jellinek","Hoffmann","Nysten"],"explicacao":"A marca elétrica de Jellinek é típica da eletricidade industrial."},{"id":5373,"materia":"ml","nivel":4,"enunciado":"O halo de fuligem no osso, em disparo encostado sobre plano ósseo, é o sinal de:","opcoes":["Benassi","Bonnet","Sommer","Puppe"],"explicacao":"Complementa o achado da câmara de mina de Hoffmann."},{"id":5374,"materia":"ml","nivel":4,"enunciado":"A lesão transversal da túnica íntima da carótida, encontrada no enforcamento, é o sinal de:","opcoes":["Amussat","Tardieu","Werkgaertner","Benassi"],"explicacao":"Indica tração forte do laço sobre o pescoço."},{"id":5375,"materia":"ml","nivel":4,"enunciado":"As manchas subpleurais maiores, claras e mal delimitadas, típicas do afogamento, são as de:","opcoes":["Paltauf","Tardieu","Lichtenberg","Brouardel"],"explicacao":"Formam-se pela diluição do sangue pela água aspirada."},{"id":5376,"materia":"igual","nivel":4,"enunciado":"Pela Lei 14.994/2024, o feminicídio passou a ser:","opcoes":["Crime autônomo, com pena de 20 a 40 anos","Apenas agravante genérica","Contravenção penal","Crime de menor potencial ofensivo, julgado no juizado especial"],"explicacao":"Está previsto no art. 121-A do Código Penal."},{"id":5377,"materia":"ml","nivel":4,"enunciado":"O método antropométrico de Bertillon, usado na identificação criminal no século XIX, foi substituído principalmente pela:","opcoes":["Datiloscopia","Odontologia legal","Fotografia comum","Grafotecnia"],"explicacao":"A datiloscopia é mais simples, barata e confiável."},{"id":5378,"materia":"ml","nivel":4,"enunciado":"No Brasil, para afirmar a identidade de duas impressões digitais, a doutrina costuma exigir pelo menos:","opcoes":["12 pontos característicos coincidentes","3 pontos característicos coincidentes","50 pontos característicos coincidentes","1 ponto característico coincidente"],"explicacao":"Não pode haver nenhuma divergência entre as impressões."},{"id":5379,"materia":"igual","nivel":0,"enunciado":"Pela Constituição, o racismo é crime:","opcoes":["Inafiançável e imprescritível","Afiançável e prescritível, sujeito a detenção","Sem pena de prisão","De ação privada"],"explicacao":"Sujeito à pena de reclusão (art. 5º, XLII)."},{"id":5380,"materia":"igual","nivel":0,"enunciado":"Pela Constituição, homens e mulheres são:","opcoes":["Iguais em direitos e obrigações","Iguais apenas no voto","Diferentes em direitos civis e iguais só nos deveres","Iguais só no trabalho"],"explicacao":"Art. 5º, I, da Constituição Federal."},{"id":5381,"materia":"igual","nivel":0,"enunciado":"O canal telefônico gratuito para denunciar violência contra a mulher é o:","opcoes":["Ligue 180","Disque 190","Disque 136","Disque 192"],"explicacao":"Funciona 24 horas, todos os dias."},{"id":5382,"materia":"igual","nivel":0,"enunciado":"A delegacia especializada no atendimento à mulher é conhecida pela sigla:","opcoes":["DEAM","DECON","DETRAN","DENARC"],"explicacao":"Atende casos de violência doméstica e sexual."},{"id":5383,"materia":"igual","nivel":0,"enunciado":"O canal para denunciar violações de direitos humanos, como racismo e maus-tratos a idosos, é o:","opcoes":["Disque 100","Disque 181","Disque 193","Disque 199"],"explicacao":"É coordenado pelo governo federal."},{"id":5384,"materia":"igual","nivel":1,"enunciado":"Pelo Estatuto da Igualdade Racial, a população negra é formada pelas pessoas que se declaram:","opcoes":["Pretas e pardas","Apenas pretas","Indígenas e amarelas","Apenas pardas"],"explicacao":"Segue o quesito cor ou raça do IBGE."},{"id":5385,"materia":"igual","nivel":1,"enunciado":"Pela Lei Maria da Penha, reter, subtrair ou destruir documentos e bens da mulher é violência:","opcoes":["Patrimonial","Moral (calúnia e difamação)","Física","Sexual"],"explicacao":"A lei prevê cinco formas: física, psicológica, sexual, patrimonial e moral."},{"id":5386,"materia":"igual","nivel":1,"enunciado":"Pela Lei Maria da Penha, humilhar, ameaçar, isolar e controlar a mulher é violência:","opcoes":["Psicológica","Patrimonial","Física","Moral"],"explicacao":"Desde 2021, a violência psicológica também é crime (art. 147-B do CP)."},{"id":5387,"materia":"igual","nivel":1,"enunciado":"O crime de perseguição (stalking), incluído no Código Penal em 2021, está no:","opcoes":["Art. 147-A","Art. 121-A","Art. 213","Art. 155"],"explicacao":"A pena aumenta se a vítima é mulher por razões da condição de sexo feminino."},{"id":5388,"materia":"igual","nivel":1,"enunciado":"A Lei 10.639/2003 tornou obrigatório nas escolas o ensino de:","opcoes":["História e cultura afro-brasileira","Língua inglesa","Educação financeira","Direito constitucional e cidadania"],"explicacao":"Em 2008, a Lei 11.645 incluiu a cultura indígena."},{"id":5389,"materia":"igual","nivel":1,"enunciado":"A Lei 14.611/2023 trata da:","opcoes":["Igualdade salarial entre mulheres e homens","Reforma da previdência dos servidores públicos federais","Lei de drogas","Proteção de dados"],"explicacao":"Exige relatórios de transparência salarial nas empresas."},{"id":5390,"materia":"igual","nivel":1,"enunciado":"A Convenção de Belém do Pará é o tratado interamericano para:","opcoes":["Prevenir, punir e erradicar a violência contra a mulher","Proteger o meio ambiente e os povos da floresta amazônica","Combater o tráfico de drogas","Regular o comércio exterior"],"explicacao":"Foi promulgada no Brasil pelo Decreto 1.973/1996."},{"id":5391,"materia":"igual","nivel":2,"enunciado":"Pela Lei Maria da Penha, as relações nela previstas independem:","opcoes":["De orientação sexual","Do sexo da vítima","Da existência de vínculo","De qualquer relação"],"explicacao":"Também protege mulheres em relações homoafetivas."},{"id":5392,"materia":"igual","nivel":2,"enunciado":"No julgamento da ADO 26, o STF decidiu que a homofobia e a transfobia:","opcoes":["Se enquadram na Lei do Racismo (Lei 7.716/1989)","Não são crimes","São contravenções penais","Só geram indenização civil, sem nenhuma consequência penal"],"explicacao":"O enquadramento vale até que o Congresso aprove lei própria."},{"id":5393,"materia":"igual","nivel":2,"enunciado":"Pela Súmula 542 do STJ, a lesão corporal em violência doméstica contra a mulher é de ação penal:","opcoes":["Pública incondicionada","Privada","Pública condicionada à representação","Privada subsidiária"],"explicacao":"Não depende da vontade da vítima para seguir."},{"id":5394,"materia":"igual","nivel":2,"enunciado":"Pela Lei Maria da Penha, aos crimes de violência doméstica contra a mulher:","opcoes":["Não se aplica a Lei 9.099/1995 (juizados especiais)","Aplica-se sempre a transação penal","Aplica-se a suspensão do processo","Cabe acordo de não persecução penal em qualquer caso, sem exceção"],"explicacao":"Art. 41 da Lei 11.340/2006."},{"id":5395,"materia":"igual","nivel":2,"enunciado":"A Lei 14.786/2023, chamada de 'Não é Não', criou protocolo para proteger mulheres em:","opcoes":["Casas noturnas, boates e shows","Escolas de ensino fundamental e médio","Hospitais públicos","Repartições fiscais"],"explicacao":"Não se aplica a cultos e eventos religiosos."},{"id":5396,"materia":"igual","nivel":2,"enunciado":"Pela Lei 15.142/2025, as cotas em concursos públicos federais passaram a reservar:","opcoes":["30% das vagas para pretos, pardos, indígenas e quilombolas","10% das vagas apenas para pretos e pardos, sem incluir indígenas","50% das vagas para escola pública","5% das vagas para negros"],"explicacao":"Substituiu a Lei 12.990/2014, que previa 20% para negros."},{"id":5397,"materia":"igual","nivel":3,"enunciado":"Pela Lei Maria da Penha, a autoridade policial deve remeter o pedido de medidas protetivas ao juiz em até:","opcoes":["48 horas","10 dias","30 dias","5 dias úteis"],"explicacao":"O juiz também tem 48 horas para decidir."},{"id":5398,"materia":"igual","nivel":3,"enunciado":"Pela Lei Maria da Penha (com a Lei 14.994/2024), descumprir medida protetiva tem pena de:","opcoes":["Reclusão de 2 a 5 anos e multa","Detenção de 15 dias a 1 mês, ou apenas multa","Apenas multa","Advertência verbal"],"explicacao":"O crime está no art. 24-A da Lei 11.340/2006."},{"id":5399,"materia":"igual","nivel":3,"enunciado":"Pela Lei Maria da Penha, a renúncia à representação da ofendida só é admitida:","opcoes":["Perante o juiz, em audiência designada para isso","Na delegacia, por escrito, diante do escrivão de polícia","Por telefone ao Ministério Público","A qualquer tempo, sem formalidade"],"explicacao":"Deve ocorrer antes do recebimento da denúncia (art. 16)."},{"id":5400,"materia":"igual","nivel":3,"enunciado":"Pela Súmula 589 do STJ, nos crimes com violência doméstica contra a mulher, o princípio da insignificância:","opcoes":["É inaplicável","Aplica-se sempre","Aplica-se só a crimes patrimoniais","Aplica-se se a vítima perdoar"],"explicacao":"A proteção da mulher afasta a ideia de lesão irrelevante."},{"id":5401,"materia":"igual","nivel":4,"enunciado":"Pela Lei Maria da Penha (art. 12-C), quando o município não é sede de comarca, o afastamento imediato do agressor do lar pode ser determinado:","opcoes":["Pelo delegado de polícia","Apenas pelo Ministério Público","Pelo prefeito","Pelo conselho tutelar"],"explicacao":"Se não houver delegado disponível, pelo policial; o juiz é comunicado em 24 horas."},{"id":5402,"materia":"igual","nivel":4,"enunciado":"Pela Lei Maria da Penha, nos casos de violência doméstica contra a mulher, é vedada a aplicação de:","opcoes":["Penas de cesta básica ou de pagamento isolado de multa","Qualquer pena privativa de liberdade em regime fechado ou semiaberto","Medidas protetivas de urgência","Prisão preventiva"],"explicacao":"Previsão do art. 17 da Lei 11.340/2006."},{"id":5403,"materia":"igual","nivel":4,"enunciado":"O Estatuto da Igualdade Racial instituiu, para organizar as políticas públicas da área, o:","opcoes":["Sinapir (Sistema Nacional de Promoção da Igualdade Racial)","SUS (Sistema Único de Saúde)","Suas (Sistema Único de Assistência Social)","Sinase (Sistema Nacional de Atendimento Socioeducativo a adolescentes)"],"explicacao":"Estados e municípios podem aderir ao sistema."},{"id":5404,"materia":"pcd","nivel":0,"enunciado":"A Lei Brasileira de Inclusão (Lei 13.146/2015) também é chamada de:","opcoes":["Estatuto da Pessoa com Deficiência","Estatuto da Pessoa Idosa e Vulnerável","Estatuto da Juventude","Estatuto da Cidade"],"explicacao":"Entrou em vigor em janeiro de 2016."},{"id":5405,"materia":"pcd","nivel":0,"enunciado":"O símbolo internacional de acesso mostra:","opcoes":["Uma pessoa em cadeira de rodas","Uma mão aberta sobre fundo azul","Um olho cortado","Um coração"],"explicacao":"Indica locais e serviços acessíveis."},{"id":5406,"materia":"pcd","nivel":0,"enunciado":"O cordão com desenhos de girassóis identifica pessoas com:","opcoes":["Deficiências ocultas","Doenças contagiosas","Prioridade por idade","Gravidez"],"explicacao":"Foi reconhecido em lei federal em 2023 (Lei 14.624)."},{"id":5407,"materia":"pcd","nivel":0,"enunciado":"A narração das cenas e imagens para pessoas cegas ou com baixa visão é a:","opcoes":["Audiodescrição","Legenda oculta","Libras","Braille"],"explicacao":"É usada em filmes, peças e programas de TV."},{"id":5408,"materia":"pcd","nivel":1,"enunciado":"Pela Lei 12.764/2012, a pessoa com transtorno do espectro autista é considerada:","opcoes":["Pessoa com deficiência, para todos os efeitos legais","Pessoa sem direito a prioridade","Absolutamente incapaz para todos os atos da vida civil","Pessoa com doença transmissível"],"explicacao":"Tem acesso às mesmas proteções da LBI."},{"id":5409,"materia":"pcd","nivel":1,"enunciado":"Pela LBI, a deficiência afeta a plena capacidade civil da pessoa para casar e ter filhos?","opcoes":["Não, a pessoa mantém o direito de casar e de ter filhos","Sim, sempre","Só se houver curatela","Depende de autorização da família ou de decisão judicial"],"explicacao":"Art. 6º da Lei 13.146/2015."},{"id":5410,"materia":"pcd","nivel":1,"enunciado":"O Dia Nacional de Luta da Pessoa com Deficiência é celebrado em:","opcoes":["21 de setembro","20 de novembro","8 de março","3 de dezembro"],"explicacao":"O dia 3 de dezembro é o Dia Internacional."},{"id":5411,"materia":"pcd","nivel":1,"enunciado":"A Carteira de Identificação da Pessoa com Transtorno do Espectro Autista (Ciptea) foi criada pela Lei:","opcoes":["13.977/2020 (Lei Romeo Mion)","11.340/2006 (Lei Maria da Penha)","8.069/1990","9.099/1995"],"explicacao":"Facilita o atendimento prioritário."},{"id":5412,"materia":"pcd","nivel":2,"enunciado":"A residência inclusiva, prevista na LBI, é destinada a jovens e adultos com deficiência:","opcoes":["Em situação de dependência e com vínculos familiares fragilizados ou rompidos","Que queiram estudar no exterior","Que trabalhem em empresas privadas","Que já tenham casa própria quitada e renda alta"],"explicacao":"É uma unidade de acolhimento do Sistema Único de Assistência Social."},{"id":5413,"materia":"pcd","nivel":2,"enunciado":"Pela Lei 8.213/1991, empresas com 100 ou mais empregados devem reservar a pessoas com deficiência ou reabilitadas:","opcoes":["De 2% a 5% dos cargos","Exatamente 20% dos cargos","1 vaga apenas","Metade dos cargos"],"explicacao":"O percentual cresce conforme o número de empregados."},{"id":5414,"materia":"pcd","nivel":2,"enunciado":"Pelo Decreto 9.508/2018, nos concursos federais, a reserva mínima de vagas para pessoas com deficiência é de:","opcoes":["5%","1%","50%","30%"],"explicacao":"A Lei 8.112/1990 permite até 20%."},{"id":5415,"materia":"pcd","nivel":3,"enunciado":"Pela LBI, praticar, induzir ou incitar discriminação de pessoa em razão de sua deficiência tem pena de:","opcoes":["Reclusão de 1 a 3 anos e multa","Detenção de 15 dias a 3 meses ou multa","Apenas multa","Advertência"],"explicacao":"Previsão do art. 88 da Lei 13.146/2015."},{"id":5416,"materia":"pcd","nivel":3,"enunciado":"Pela LBI, abandonar pessoa com deficiência em hospitais, casas de saúde ou abrigos tem pena de:","opcoes":["Reclusão de 6 meses a 3 anos e multa","Apenas multa","Detenção de 10 a 20 anos","Advertência e prestação de serviços à comunidade por um ano"],"explicacao":"Previsão do art. 90 da Lei 13.146/2015."},{"id":5417,"materia":"pcd","nivel":4,"enunciado":"Pela LBI, se a discriminação de pessoa com deficiência é cometida por meio de comunicação social ou publicação, a pena é de:","opcoes":["Reclusão de 2 a 5 anos e multa","Reclusão de 1 a 3 anos e multa","Detenção de 1 a 6 meses","Apenas multa"],"explicacao":"O juiz pode mandar recolher o material e retirar a publicação."},{"id":5418,"materia":"pcd","nivel":4,"enunciado":"Pela LBI, a pena do crime de discriminação de pessoa com deficiência aumenta de 1/3 quando:","opcoes":["A vítima está sob cuidado e responsabilidade do agente","O crime ocorre em dia útil","A vítima tem mais de 18 anos","O agente é réu primário, de bons antecedentes e confessa o crime"],"explicacao":"Previsão do art. 88, § 1º, da Lei 13.146/2015."},{"id":5419,"materia":"ia","nivel":0,"enunciado":"A tecnologia que transforma texto de uma imagem ou documento escaneado em texto editável é o:","opcoes":["OCR (reconhecimento óptico de caracteres)","GPS (sistema de posicionamento global)","Bluetooth","Wi-Fi"],"explicacao":"É usada para digitalizar documentos e boletins antigos."},{"id":5420,"materia":"ia","nivel":0,"enunciado":"Uma sequência finita de passos para resolver um problema é um:","opcoes":["Algoritmo","Hardware","Protocolo de rede","Navegador"],"explicacao":"Sistemas de IA são construídos a partir de algoritmos."},{"id":5421,"materia":"ia","nivel":1,"enunciado":"A área da IA que permite ao computador entender e produzir a linguagem humana é o:","opcoes":["Processamento de linguagem natural (PLN)","Processamento de imagens médicas em alta resolução","Armazenamento em nuvem","Banco de dados relacional"],"explicacao":"Está por trás de tradutores e chatbots."},{"id":5422,"materia":"ia","nivel":1,"enunciado":"A área da IA que permite ao computador interpretar imagens e vídeos é a:","opcoes":["Visão computacional","Computação em nuvem","Criptografia","Robótica industrial"],"explicacao":"É usada, por exemplo, para ler placas de veículos."},{"id":5423,"materia":"ia","nivel":1,"enunciado":"O teste de Turing busca avaliar se uma máquina:","opcoes":["Conversa de modo indistinguível de um humano","Calcula mais rápido que um humano em qualquer tarefa","Tem acesso à internet","Consome menos energia"],"explicacao":"Foi proposto por Alan Turing em 1950."},{"id":5424,"materia":"ia","nivel":2,"enunciado":"Em reconhecimento facial, o falso positivo ocorre quando o sistema:","opcoes":["Aponta como a mesma pessoa alguém que não é","Não encontra ninguém no banco","Reconhece corretamente o suspeito procurado pela polícia","Desliga a câmera"],"explicacao":"Por isso, o resultado deve ser confirmado por outros meios de prova."},{"id":5425,"materia":"ia","nivel":2,"enunciado":"Estudos mostram que sistemas de reconhecimento facial mal treinados erram mais com:","opcoes":["Pessoas negras e mulheres","Pessoas de olhos claros","Homens brancos de meia-idade","Fotos de alta resolução"],"explicacao":"É um exemplo de viés algorítmico ligado aos dados de treino."},{"id":5426,"materia":"ia","nivel":3,"enunciado":"Overfitting (sobreajuste) ocorre quando o modelo:","opcoes":["Decora os dados de treino e vai mal com dados novos","Aprende bem padrões gerais e acerta com dados novos","Tem poucos parâmetros","Nunca foi treinado"],"explicacao":"Separar dados de treino e de teste ajuda a detectar o problema."},{"id":5427,"materia":"ia","nivel":3,"enunciado":"O AI Act da União Europeia regula a inteligência artificial com abordagem baseada:","opcoes":["No risco de cada uso","Apenas no preço dos sistemas","Só no país de origem do fornecedor","No tamanho da empresa"],"explicacao":"Usos de risco inaceitável são proibidos; os de alto risco têm regras rígidas."},{"id":5428,"materia":"ia","nivel":4,"enunciado":"O policiamento preditivo baseado em dados históricos de ocorrências pode gerar o risco de:","opcoes":["Reforçar vieses e concentrar vigilância nos mesmos bairros","Eliminar totalmente a necessidade de policiais e de investigação nas ruas","Garantir decisões sempre neutras","Impedir qualquer crime futuro"],"explicacao":"Se os dados refletem abordagens desiguais, o modelo repete o padrão."},{"id":5429,"materia":"sust","nivel":0,"enunciado":"Os chamados '3 Rs' da sustentabilidade são:","opcoes":["Reduzir, reutilizar e reciclar","Recolher, remover e reformar","Reparar, rever e renovar os bens","Reter, revender e repetir"],"explicacao":"Reduzir o consumo vem em primeiro lugar."},{"id":5430,"materia":"sust","nivel":0,"enunciado":"A quantidade total de gases de efeito estufa emitida por uma pessoa, empresa ou produto é a:","opcoes":["Pegada de carbono","Pegada hídrica","Matriz energética","Camada de ozônio"],"explicacao":"Pode ser reduzida com menos consumo de energia fóssil e menos desperdício."},{"id":5431,"materia":"sust","nivel":1,"enunciado":"O Acordo de Paris busca limitar o aquecimento global a:","opcoes":["Bem abaixo de 2 °C, com esforço para 1,5 °C","Exatamente 5 °C","Nenhum limite definido","3 °C até o fim do século, sem metas"],"explicacao":"Os países apresentam metas chamadas NDCs."},{"id":5432,"materia":"sust","nivel":1,"enunciado":"O ODS 5 da Agenda 2030 trata de:","opcoes":["Igualdade de gênero","Vida na água e oceanos","Fome zero","Energia limpa"],"explicacao":"Inclui eliminar a violência contra mulheres e meninas."},{"id":5433,"materia":"sust","nivel":1,"enunciado":"O ODS 6 da Agenda 2030 trata de:","opcoes":["Água potável e saneamento","Educação de qualidade","Indústria, inovação e infraestrutura","Paz e justiça"],"explicacao":"Busca acesso universal à água e ao esgoto tratado."},{"id":5434,"materia":"sust","nivel":2,"enunciado":"Na Política Nacional de Resíduos Sólidos, o retorno de produtos usados ao fabricante, como pilhas e pneus, é a:","opcoes":["Logística reversa","Coleta convencional","Compostagem doméstica","Incineração"],"explicacao":"Prevista na Lei 12.305/2010."},{"id":5435,"materia":"sust","nivel":2,"enunciado":"Pela Lei 9.605/1998, nos crimes ambientais, a pessoa jurídica:","opcoes":["Pode ser responsabilizada penalmente","Nunca responde por crime","Só responde civilmente","Só responde civilmente, por meio de multa administrativa"],"explicacao":"A Constituição também prevê essa responsabilidade (art. 225, § 3º)."},{"id":5436,"materia":"sust","nivel":3,"enunciado":"Pela Lei 12.305/2010, a ordem de prioridade na gestão de resíduos começa por:","opcoes":["Não geração e redução","Disposição final em aterro","Incineração","Reciclagem"],"explicacao":"Depois: reutilização, reciclagem, tratamento e disposição final adequada."},{"id":5437,"materia":"sust","nivel":3,"enunciado":"A Lei 15.042/2024 instituiu o:","opcoes":["Sistema Brasileiro de Comércio de Emissões (SBCE)","Código Florestal","Estatuto da Cidade","Sistema Nacional de Unidades de Conservação da Natureza"],"explicacao":"Cria um mercado regulado de carbono no Brasil."},{"id":5438,"materia":"sust","nivel":4,"enunciado":"Pela Lei 9.605/1998, entre as penas aplicáveis à pessoa jurídica estão:","opcoes":["Multa, restritivas de direitos e prestação de serviços à comunidade","Prisão do CNPJ","Reclusão em regime fechado dos sócios, dos diretores e do próprio CNPJ da empresa","Apenas advertência verbal"],"explicacao":"A prestação de serviços inclui custear programas ambientais."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('ml','igual','pcd','ia','sust') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
